CREATE TABLE [purchase].[PurchaseAttachments]([PurchaseAttachmentId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PurchaseAttachments_Id] DEFAULT NEWSEQUENTIALID(),[PurchaseInvoiceId] UNIQUEIDENTIFIER NOT NULL,[FileName] NVARCHAR(255) NOT NULL,[ContentType] NVARCHAR(100) NOT NULL,[FileData] VARBINARY(MAX) NOT NULL,[UploadedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_PurchaseAttachments_Uploaded] DEFAULT SYSUTCDATETIME(),[UploadedBy] NVARCHAR(256) NULL,[IsDeleted] BIT NOT NULL CONSTRAINT [DF_PurchaseAttachments_Deleted] DEFAULT 0,CONSTRAINT [PK_PurchaseAttachments] PRIMARY KEY([PurchaseAttachmentId]),CONSTRAINT [FK_PurchaseAttachments_Invoice] FOREIGN KEY([PurchaseInvoiceId]) REFERENCES [purchase].[PurchaseInvoices]([PurchaseInvoiceId]) ON DELETE CASCADE);
